/**
 * AI KSHETRA 2026 - Certificate PDF Download Utilities
 * NEXAA - Next Gen Engineers & AI Association
 * R.V.R. & J.C. College of Engineering, Guntur
 *
 * Architecture Note:
 * Certificates are now fully generated by the Python script as PDF files.
 * This module handles fetching and downloading those pre-generated static PDFs.
 * The old in-browser HTML certificate rendering has been removed.
 */

(function (window) {
  'use strict';

  /**
   * Downloads a pre-generated Python PDF certificate.
   * Fetches the static PDF from certificates/<certId>.pdf and triggers a browser download.
   * @param {string} certId - Certificate ID (e.g. AIK26-0001)
   * @param {HTMLElement|null} btnEl - Optional button element to show loading state
   * @returns {Promise<boolean>} true if download succeeded, false otherwise
   */
  async function downloadPdf(certId, btnEl) {
    const cleanId = (certId || '').trim().toUpperCase();
    if (!cleanId) {
      console.error('> [AI_CERT] downloadPdf called with empty certId');
      return false;
    }

    const filename = 'AI_Kshetra_2026_Certificate_' + cleanId + '.pdf';
    const pdfUrl = window.AI_CONFIG.getCertificatePdfUrl(cleanId);

    const originalText = btnEl ? btnEl.innerHTML : null;
    if (btnEl) {
      btnEl.innerHTML = '[ PREPARING... ]';
      btnEl.disabled = true;
    }

    try {
      const response = await fetch(pdfUrl);
      if (!response.ok) {
        throw new Error('HTTP_' + response.status + ': PDF not found on server.');
      }
      const blob = await response.blob();
      if (blob.size < 100) {
        throw new Error('PDF_EMPTY: Received empty file response.');
      }

      const blobUrl = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = blobUrl;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      setTimeout(() => URL.revokeObjectURL(blobUrl), 10000);
      return true;
    } catch (err) {
      console.error('> [AI_CERT] PDF download failed for ' + cleanId + ':', err.message);
      alert('> ERROR: Could not download certificate PDF.\n' + err.message + '\n\nIf the problem persists, contact NEXAA support.');
      return false;
    } finally {
      if (btnEl && originalText !== null) {
        btnEl.innerHTML = originalText;
        btnEl.disabled = false;
      }
    }
  }

  window.AI_CERT = {
    downloadPdf
  };

})(window);